 "assam engineering college":["Chemical Engineering","Civil Engineering","Computer Science and Engineering","Electrical Engineering","Electronics and Telecommunication Engineering","Industrial and Production Engineering","Instrumentation Engineering","Mechanical Engineering"],
 "jorhat engineering college":["Civil Engineering","Mechanical Engineering","Electrical Engineering","Computer Science and Engineering","Instrumentation Engineering"],
