const isOfficialBranch=(collegeName:string|undefined,branchName:string|undefined)=>{if(!collegeName||!branchName)return false;const allowed=OFFICIAL_BRANCHES[collegeName.trim().toLowerCase()];return !allowed||allowed.some(x=>x.toLowerCase()===branchName.trim().toLowerCase());};
const subjects=[{slug:"physics",name:"Physics"},{slug:"mathematics",name:"Mathematics"},{slug:"chemistry",name:"Chemistry"}];
const years=Array.from({length:9},(_,i)=>2018+i);
const fmt=(v:any)=>Number(v||0).toLocaleString("en-IN");
const pct=(v:number)=>v.toFixed(1)+"%";
function useRows(table:string,fields="*"){const [rows,setRows]=useState<R[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{let live=true;if(!supabase){setError("Supabase is not configured.");setLoading(false);return;}supabase.from(table).select(fields).range(0,4999).then(({data,error})=>{if(!live)return;setRows(data||[]);setError(error?.message||"");setLoading(false)});return()=>{live=false}},[table,fields]);return {rows,loading,error};}
function Loading({label="Loading your analysis"}:{label?:string}){return <div className="intel-loading v2-loading"><LoaderCircle className="spin"/><span>{label}</span></div>}
function Empty({title,children}:{title:string;children:string}){return <div className="intel-empty"><Info/><b>{title}</b><p>{children}</p></div>}
function Shell({title,desc,children}:{title:string;desc:string;children:React.ReactNode}){const loc=useLocation(),adminReturn=loc.search.includes("fromAdmin=1"),home=loc.pathname==="/analytics";const back=adminReturn?"/admin?tab=intelligence":home?"/":"/analytics";return <main className="intel-page v2-page"><div className="intel-nav"><Link className="intel-back intel-back-button" to={back}>{adminReturn?<ArrowLeft size={16}/>:home?<Home size={16}/>:<ArrowLeft size={16}/>} {adminReturn?"Back to Admin Console":home?"Back to SmartPrep Axom":"Back to Intelligence"}</Link><span>CEE 2027 WORKSPACE</span></div><header className="intel-hero v2-hero"><div><span className="intel-eyebrow">SMARTPREP AXOM · CEE INTELLIGENCE</span><h1>{title}</h1><p>{desc}</p></div><ChartNoAxesCombined size={38}/></header>{children}</main>}
function Stat({label,value,note}:{label:string;value:string;note?:string}){return <div className="intel-stat"><span>{label}</span><strong>{value}</strong>{note&&<small>{note}</small>}</div>}
function Select({label,value,onChange,children}:{label:string;value:string;onChange:(v:string)=>void;children:React.ReactNode}){const options=React.Children.toArray(children).filter((child:any)=>React.isValidElement(child)&&child.type==="option").map((child:any)=>({value:String(child.props.value??child.props.children),label:String(child.props.children)}));return <SmartSelect label={label} value={value} onChange={onChange} options={options} searchable={false}/>}
function SubjectTabs({value,onChange}:{value:string;onChange:(v:string)=>void}){return <div className="intel-tabs">{subjects.map(s=><button key={s.slug} className={value===s.slug?"active":""} onClick={()=>onChange(s.slug)}>{s.name}</button>)}</div>}
function PYQ(){const {rows:q,loading,error}=useRows("cee_question_analytics","exam_year,question_number,subject_id,chapter_id,difficulty,classification_confidence,source_page");const {rows:c,loading:cl}=useRows("chapters","id,name,slug,subject_id,display_order");const {rows:s,loading:sl}=useRows("subjects","id,name,slug");const [subject,setSubject]=useState("physics"),[from,setFrom]=useState("2018"),[to,setTo]=useState("2026"),[chapter,setChapter]=useState("all"),[sort,setSort]=useState("questions"),[search,setSearch]=useState("");const subjectRow=s.find(x=>x.slug===subject);const selected=q.filter(x=>Number(x.exam_year)>=Number(from)&&Number(x.exam_year)<=Number(to)&&(!subjectRow||x.subject_id===subjectRow.id));const chapters=c.filter(x=>!subjectRow||x.subject_id===subjectRow.id);const yearList=years.filter(y=>y>=Number(from)&&y<=Number(to));const rows=chapters.map(ch=>{const matched=selected.filter(x=>x.chapter_id===ch.id);const yearCounts:Record<string,number>={};for(const item of matched)yearCounts[String(item.exam_year)]=(yearCounts[String(item.exam_year)]||0)+1;const appeared=Object.keys(yearCounts).length;return {ch,matched,yearCounts,appeared,total:matched.length,avg:yearList.length?matched.length/yearList.length:0,weight:selected.length?matched.length/selected.length*100:0,recurrence:yearList.length?appeared/yearList.length*100:0};}).filter(x=>(chapter==="all"||x.ch.id===chapter)&&x.ch.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==="questions"?b.total-a.total:sort==="recurrence"?b.recurrence-a.recurrence:sort==="weight"?b.weight-a.weight:a.ch.name.localeCompare(b.ch.name));const total=selected.length,classifiedChapters=new Set(selected.map(x=>x.chapter_id).filter(Boolean)).size;return <Shell title="Chapter-wise PYQ trends" desc="Question frequency, chapter weightage and recurrence across every selectable Assam CEE year range."><SubjectTabs value={subject} onChange={v=>{setSubject(v);setChapter("all")}}/><section className="intel-panel v2-filter-panel"><div className="v2-filter-heading"><SlidersHorizontal/><div><b>Build your historical range</b><small>Choose any start and end year, subject and chapter</small></div></div><div className="v2-grid-4"><Select label="From year" value={from} onChange={v=>{setFrom(v);if(Number(v)>Number(to))setTo(v)}}>{years.map(y=><option key={y}>{y}</option>)}</Select><Select label="To year" value={to} onChange={setTo}>{years.filter(y=>y>=Number(from)).map(y=><option key={y}>{y}</option>)}</Select><Select label="Chapter" value={chapter} onChange={setChapter}><option value="all">All chapters</option>{chapters.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</Select><Select label="Rank by" value={sort} onChange={setSort}><option value="questions">Question count</option><option value="weight">Weightage</option><option value="recurrence">Recurrence</option><option value="name">Chapter name</option></Select></div><label className="intel-search v2-search"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search chapter…"/></label></section>{loading||cl||sl?<Loading label="Reading classified question records…"/>:error?<Empty title="Could not load the analytics dataset">{error}</Empty>:<><div className="intel-stats"><Stat label="Classified questions" value={fmt(total)} note={from+"–"+to}/><Stat label="Years selected" value={fmt(yearList.length)}/><Stat label="Chapters represented" value={fmt(classifiedChapters)}/></div>{!total?<Empty title="No classified source records yet">The analytics database is ready, but this range has no published classifications yet. Only questions mapped from the original papers are counted; no question totals are fabricated.</Empty>:<section className="trend-list-panel"><div className="trend-list-head"><div><h2>{subjectRow?.name||"All subjects"} · chapter breakdown</h2><p>{from}–{to} · {total} source-classified questions</p></div></div><div className="v2-year-strip">{yearList.map(y=><span key={y}>{y}</span>)}</div><div className="trend-card-list">{rows.map((x,i)=><article className="trend-card" key={x.ch.id}><div className="trend-card-top"><span className="trend-rank">#{i+1}</span><div className="trend-chapter"><b>{x.ch.name}</b><small>{x.appeared} of {yearList.length} years represented</small></div><strong className="trend-q-count">{fmt(x.total)}<small> Qs</small></strong></div><div className="trend-metrics"><div><small>AVG / YEAR</small><b>{x.avg.toFixed(2)}</b></div><div><small>SUBJECT WEIGHTAGE</small><b>{pct(x.weight)}</b></div><div><small>RECURRENCE</small><b>{pct(x.recurrence)}</b></div><div><small>RECORDS</small><b>{x.total}</b></div></div><div className="v2-mini-chart">{yearList.map(y=>{const val=x.yearCounts[String(y)]||0,max=Math.max(1,...Object.values(x.yearCounts));return <div key={y} title={y+": "+val+" questions"}><b>{val||"–"}</b><i><em style={{height:(val/max*100)+"%"}}/></i><small>{String(y).slice(2)}</small></div>})}</div></article>)}</div></section>}</>}</Shell>}
function Difficulty(){const {rows:q,loading,error}=useRows("cee_question_analytics","exam_year,question_number,subject_id,chapter_id,difficulty,classification_confidence,source_page");const {rows:c}=useRows("chapters","id,name,subject_id");const {rows:s}=useRows("subjects","id,name,slug");const [from,setFrom]=useState("2018"),[to,setTo]=useState("2026"),[subject,setSubject]=useState("all"),[chapter,setChapter]=useState("all"),[mode,setMode]=useState("actual");const subj=s.find(x=>x.slug===subject);const filtered=q.filter(x=>Number(x.exam_year)>=Number(from)&&Number(x.exam_year)<=Number(to)&&(!subj||x.subject_id===subj.id)&&(chapter==="all"||x.chapter_id===chapter));const classified=filtered.filter(x=>["easy","moderate","hard"].includes(String(x.difficulty).toLowerCase()));const counts={easy:classified.filter(x=>x.difficulty==="easy").length,moderate:classified.filter(x=>x.difficulty==="moderate").length,hard:classified.filter(x=>x.difficulty==="hard").length};const total=classified.length;const rows=c.filter(x=>!subj||x.subject_id===subj.id).map(ch=>{const list=filtered.filter(x=>x.chapter_id===ch.id&&["easy","moderate","hard"].includes(String(x.difficulty).toLowerCase()));const n=list.length;return {ch,n,hard:n?list.filter(x=>x.difficulty==="hard").length/n*100:0,moderate:n?list.filter(x=>x.difficulty==="moderate").length/n*100:0,easy:n?list.filter(x=>x.difficulty==="easy").length/n*100:0};}).filter(x=>x.n).sort((a,b)=>b.hard-a.hard);const yearsAvailable=years.filter(y=>y>=Number(from)&&y<=Number(to));const subjectRows=subjects.map(x=>{const sr=s.find(v=>v.slug===x.slug);const arr=classified.filter(v=>!sr||v.subject_id===sr.id);const n=arr.length;return {name:x.name,n,hard:n?arr.filter(v=>v.difficulty==="hard").length/n*100:0,moderate:n?arr.filter(v=>v.difficulty==="moderate").length/n*100:0,easy:n?arr.filter(v=>v.difficulty==="easy").length/n*100:0}});return <Shell title="CEE examination difficulty" desc="Compare observed question difficulty by year, subject and chapter, with a separate pattern-based outlook for CEE 2027."><section className="intel-panel v2-filter-panel"><div className="v2-grid-4"><Select label="From year" value={from} onChange={v=>{setFrom(v);if(Number(v)>Number(to))setTo(v)}}>{years.map(y=><option key={y}>{y}</option>)}</Select><Select label="To year" value={to} onChange={setTo}>{years.filter(y=>y>=Number(from)).map(y=><option key={y}>{y}</option>)}</Select><Select label="Subject" value={subject} onChange={v=>{setSubject(v);setChapter("all")}}><option value="all">All subjects</option>{subjects.map(x=><option key={x.slug} value={x.slug}>{x.name}</option>)}</Select><Select label="Chapter" value={chapter} onChange={setChapter}><option value="all">All chapters</option>{c.filter(x=>!subj||x.subject_id===subj.id).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</Select></div><div className="v2-mode-tabs"><button className={mode==="actual"?"active":""} onClick={()=>setMode("actual")}>Observed difficulty</button><button className={mode==="forecast"?"active":""} onClick={()=>setMode("forecast")}>2027 difficulty outlook</button></div></section>{loading?<Loading label="Analysing classified question difficulty…"/>:error?<Empty title="Could not load difficulty records">{error}</Empty>:mode==="forecast"?<><div className="intel-note"><Info/>The 2027 outlook is an estimate from the selected historical questions, not an official paper blueprint. Difficulty labels are analyst assessments of question complexity, not student-response statistics.</div><div className="intel-stats"><Stat label="Classified questions" value={fmt(total)} note={from+"–"+to}/><Stat label="Hard share" value={total?pct(counts.hard/total*100):"—"}/><Stat label="Years selected" value={fmt(yearsAvailable.length)}/></div><section className="intel-panel"><h2>Historical challenge signals by chapter</h2>{rows.length?rows.map(x=><div className="v2-difficulty-row" key={x.ch.id}><b>{x.ch.name}</b><span>{pct(x.hard)} hard · {x.n} classified questions</span><i><em style={{width:x.hard+"%"}}/></i></div>):<Empty title="Not enough classified chapter difficulty records">Once difficulty classifications are loaded, this view ranks chapters by the share of challenging questions.</Empty>}</section><section className="intel-panel"><h2>Subject difficulty pattern</h2>{subjectRows.filter(x=>x.n).map(x=><div className="v2-difficulty-row" key={x.name}><b>{x.name}</b><span>{pct(x.easy)} easy · {pct(x.moderate)} moderate · {pct(x.hard)} hard · {x.n} questions</span><i><em style={{width:x.hard+"%"}}/></i></div>)}</section></>:<><div className="intel-stats"><Stat label="Difficulty-classified" value={fmt(total)} note={from+"–"+to}/><Stat label="Easy" value={fmt(counts.easy)} note={total?pct(counts.easy/total*100):"—"}/><Stat label="Moderate" value={fmt(counts.moderate)} note={total?pct(counts.moderate/total*100):"—"}/><Stat label="Hard" value={fmt(counts.hard)} note={total?pct(counts.hard/total*100):"—"}/></div>{!total?<Empty title="Difficulty classifications are not loaded for this range">The view is connected to the dedicated CEE analytics dataset. It will show only questions whose difficulty has been assessed from the original paper.</Empty>:<><section className="intel-panel"><h2>Observed difficulty distribution</h2>{Object.entries(counts).map(([k,v])=><div className="intel-difficulty" key={k}><span>{k.toUpperCase()} · {fmt(v)} · {pct(v/total*100)}</span><i><em className={"diff-"+k} style={{width:(v/total*100)+"%"}}/></i></div>)}</section><section className="intel-panel"><h2>Hardest chapters in this selection</h2>{rows.slice(0,12).map(x=><div className="v2-difficulty-row" key={x.ch.id}><b>{x.ch.name}</b><span>{pct(x.hard)} hard · n={x.n}</span><i><em style={{width:x.hard+"%"}}/></i></div>)}</section></>}</>}</Shell>}
function Predictions(){const {rows:q,loading,error}=useRows("cee_question_analytics","exam_year,question_number,subject_id,chapter_id,difficulty,classification_confidence,source_page");const {rows:c}=useRows("chapters","id,name,subject_id,display_order");const {rows:s}=useRows("subjects","id,name,slug");const [selected,setSelected]=useState(["physics","mathematics","chemistry"]),[from,setFrom]=useState("2018"),[to,setTo]=useState("2026");const toggle=(slug:string)=>setSelected(old=>old.includes(slug)?old.filter(x=>x!==slug):[...old,slug]);const range=years.filter(y=>y>=Number(from)&&y<=Number(to));const filtered=q.filter(x=>Number(x.exam_year)>=Number(from)&&Number(x.exam_year)<=Number(to));const output=selected.flatMap(slug=>{const subj=s.find(x=>x.slug===slug);if(!subj)return [];return c.filter(ch=>ch.subject_id===subj.id).map(ch=>{const records=filtered.filter(x=>x.subject_id===subj.id&&x.chapter_id===ch.id);const yearCounts=range.map(y=>records.filter(x=>Number(x.exam_year)===y).length);const total=yearCounts.reduce((a,b)=>a+b,0);const appeared=yearCounts.filter(x=>x>0).length;const recurrence=range.length?appeared/range.length*100:0;const avg=range.length?total/range.length:0;const recent=yearCounts.slice(-Math.min(3,yearCounts.length)).reduce((a,b)=>a+b,0);const recentAvg=Math.min(100,range.length?recent/Math.max(1,Math.min(3,range.length))*3:0);const maxAvg=Math.max(1,...c.filter(x=>x.subject_id===subj.id).map(ch2=>{const n=filtered.filter(x=>x.subject_id===subj.id&&x.chapter_id===ch2.id).length;return range.length?n/range.length:0}));const score=0.5*recurrence+0.3*(avg/maxAvg*100)+0.2*recentAvg;return {subject:subj.name,chapter:ch.name,count:total,recurrence,average:avg,score,years:appeared,priority:score>=65?"High":score>=40?"Medium":"Watch"};}).filter(x=>x.count>0);}).sort((a,b)=>b.score-a.score);const total=filtered.length;return <Shell title="Assam CEE 2027 chapter priorities" desc="Subject-specific priority lists based on chapter recurrence, frequency and recent-year momentum."><section className="intel-panel v2-filter-panel"><div className="v2-filter-heading"><Sparkles/><div><b>Historical pattern selector</b><small>Every start/end combination is supported, including 2018–2020 and 2023–2024</small></div></div><div className="v2-subject-picks">{subjects.map(x=><label key={x.slug} className={selected.includes(x.slug)?"selected":""}><input type="checkbox" checked={selected.includes(x.slug)} onChange={()=>toggle(x.slug)}/><span>{x.name}</span></label>)}</div><div className="v2-grid-2"><Select label="Historical data from" value={from} onChange={v=>{setFrom(v);if(Number(v)>Number(to))setTo(v)}}>{years.map(y=><option key={y}>{y}</option>)}</Select><Select label="Historical data to" value={to} onChange={setTo}>{years.filter(y=>y>=Number(from)).map(y=><option key={y}>{y}</option>)}</Select></div></section>{loading?<Loading label="Calculating chapter priorities…"/>:error?<Empty title="Could not load prediction data">{error}</Empty>:!output.length?<Empty title="No classified historical questions in this range">The selected range currently has no published chapter classifications. Once source-based records are loaded, this will rank the chapters without inventing predicted question counts.</Empty>:<><div className="intel-stats"><Stat label="Subjects selected" value={String(selected.length)}/><Stat label="Chapters ranked" value={fmt(output.length)}/><Stat label="Classified questions" value={fmt(total)}/><Stat label="Historical range" value={from+"–"+to}/></div><div className="intel-note"><Info/>Priority score combines recurrence (50%), average frequency (30%) and recent three-year momentum (20%). It ranks preparation priority; it is not a guaranteed question count or an official prediction.</div><section className="intel-panel"><h2>2027 subject-wise priority list</h2><div className="intel-predictions">{output.map(x=><article className={"intel-prediction "+(x.priority==="High"?"high":x.priority==="Medium"?"moderate":"lower")} key={x.subject+x.chapter}><div><small>{x.subject} · {x.priority.toUpperCase()} PRIORITY</small><b>{x.chapter}</b><small>{x.count} questions · {pct(x.recurrence)} recurrence · {x.years} years appeared</small></div><strong>{Math.round(x.score)}<small> priority</small></strong></article>)}</div></section></>}</Shell>}
type CEEForecastBand={marksMin:number;marksMax:number;rankMin:number;rankMax:number;marksLabel:string;rankLabel:string;note?:string};
type CEEForecastSource={name:string;url:string;publishedOrUpdated:string;sourceType:string;supports:string};
type CEEForecastData={model:string;marksMinimum:number;marksMaximum:number;rankMinimum:number;rankMaximum:number;description:string;method:string;bands:CEEForecastBand[];sources:CEEForecastSource[];officialReference:{title:string;url:string;note:string}};
type VerifiedCutoffAnchor={rank:number;marks:number;year:number;college:string;branch:string;round:string;quota:string};
type OfficialScoreRankPoint={exam_year:number;score:number;merit_rank:number};
function interpolateOfficialScoreRank(points:OfficialScoreRankPoint[],value:number,mode:"marks"|"rank"):number|null{
 const axis=mode==="marks"?"score":"merit_rank",target=mode==="marks"?"merit_rank":"score";
 const sorted=[...points].filter(p=>Number.isFinite(p[axis])&&Number.isFinite(p[target])).sort((a,b)=>a[axis]-b[axis]);
 if(!sorted.length)return null;if(sorted.length===1)return sorted[0][target];
 if(value<=sorted[0][axis])return sorted[0][target];if(value>=sorted[sorted.length-1][axis])return sorted[sorted.length-1][target];
 for(let i=1;i<sorted.length;i++){const a=sorted[i-1],b=sorted[i];if(value<=b[axis]){const span=b[axis]-a[axis];if(span<=0)return b[target];const t=(value-a[axis])/span;return a[target]+t*(b[target]-a[target]);}}
 return sorted[sorted.length-1][target];
}
function medianNumber(values:number[]){const sorted=[...values].sort((a,b)=>a-b);if(!sorted.length)return null;const mid=Math.floor(sorted.length/2);return sorted.length%2?sorted[mid]:(sorted[mid-1]+sorted[mid])/2;}

const rankCurve=[{marks:55,rank:6500},{marks:62.5,rank:5750},{marks:78,rank:4250},{marks:93.5,rank:3000},{marks:109.5,rank:2150},{marks:129.5,rank:1500},{marks:150,rank:1000},{marks:173,rank:600},{marks:208,rank:400},{marks:250,rank:200},{marks:295.5,rank:150},{marks:320,rank:100},{marks:480,rank:1}];
function interpolateRankFromMarks(marks:number){
 if(marks<=55)return 6500;
 for(let i=1;i<rankCurve.length;i++){const a=rankCurve[i-1],b=rankCurve[i];if(marks<=b.marks){const t=(marks-a.marks)/(b.marks-a.marks);return Math.max(1,Math.min(6500,Math.round(a.rank+t*(b.rank-a.rank))))}}
 return 1;
}
function interpolateMarksFromRank(rank:number){
 const byRank=[...rankCurve].sort((a,b)=>a.rank-b.rank);
 for(let i=1;i<byRank.length;i++){const a=byRank[i-1],b=byRank[i];if(rank<=b.rank){const t=(rank-a.rank)/(b.rank-a.rank);return Math.max(50,Math.min(480,Math.round((a.marks+t*(b.marks-a.marks))*10)/10))}}
 return 480;
}
function findMarksBand(bands:CEEForecastBand[],marks:number){return bands.find(b=>marks>=b.marksMin&&marks<=b.marksMax)||null}
function findRankBand(bands:CEEForecastBand[],rank:number){
 if(rank<=200)return {marksMin:320,marksMax:480,marksLabel:"320–480+ marks",rankMin:1,rankMax:200,rankLabel:"1–200"};
 if(rank<=300)return {marksMin:229,marksMax:271,marksLabel:"229–271 marks",rankMin:201,rankMax:300,rankLabel:"201–300"};
 const b=bands.filter(x=>x.marksMin>=55).find(x=>rank>=x.rankMin&&rank<=x.rankMax);
 return b?{...b,rankLabel:b.rankMin.toLocaleString("en-IN")+"–"+b.rankMax.toLocaleString("en-IN")}:null;
}
function Rank(){
 const {rows:cutoffs,loading:cutoffLoading,error:cutoffError}=useRows("admission_cutoffs","id,admission_year,category_id,institution_id,branch_id,counselling_round_id,quota_code,closing_rank,closing_marks,verification_status,source_document_id");
 const {rows:categories,loading:categoryLoading}=useRows("admission_categories","id,code,name");
 const {rows:sources,loading:sourceLoading}=useRows("admission_source_documents","id,title,source_url,admission_year,source_authority,document_type,verification_status");
 const {rows:institutions}=useRows("engineering_institutions","id,name");
 const {rows:branches}=useRows("engineering_branches","id,name");
 const {rows:rounds}=useRows("counselling_rounds","id,admission_year,round_name");
 const {rows:scoreRankPoints,loading:scoreRankLoading}=useRows("cee_score_rank_points","id,exam_year,total_marks,score,merit_rank,verification_status,source_document_id");
 const [estimateData,setEstimateData]=useState<CEEForecastData|null>(null),[estimateError,setEstimateError]=useState("");
 const [mode,setMode]=useState<"marks"|"rank">("marks"),[input,setInput]=useState("200"),[generated,setGenerated]=useState(false);
 useEffect(()=>{let live=true;fetch("/data/cee-rank-estimates.json").then(r=>{if(!r.ok)throw new Error("Could not load the rank reference data.");return r.json()}).then(json=>{if(live)setEstimateData(json as CEEForecastData)}).catch(e=>{if(live)setEstimateError(e instanceof Error?e.message:"Could not load rank data.")});return()=>{live=false}},[]);
 const verified:VerifiedCutoffAnchor[]=cutoffs.flatMap(x=>{
  const source=sources.find(s=>s.id===x.source_document_id),category=categories.find(c=>c.id===x.category_id),year=Number(x.admission_year),quota=String(x.quota_code||"");
  const allowedQuota=["all_seats","excluding_5_percent","5_percent_reservation","regular"].includes(quota);
  const marks=Number(x.closing_marks),rank=Number(x.closing_rank);
  if(!allowedQuota||x.verification_status!=="verified"||source?.verification_status!=="verified"||source?.source_authority!=="DTE Assam"||source?.document_type!=="cutoff"||category?.code!=="UR"||x.closing_marks==null||x.closing_marks===""||!Number.isFinite(rank)||rank<1||rank>6500||!Number.isFinite(marks)||marks<1||marks>480)return [];
  return [{rank,marks,year,college:institutions.find(i=>i.id===x.institution_id)?.name||"Engineering college",branch:branches.find(b=>b.id===x.branch_id)?.name||"Branch",round:rounds.find(r=>r.id===x.counselling_round_id)?.round_name||"Counselling round",quota}];
 });
 const verifiedOfficialPoints:OfficialScoreRankPoint[]=scoreRankPoints.flatMap(x=>{const source=sources.find(s=>s.id===x.source_document_id),year=Number(x.exam_year),score=Number(x.score),rank=Number(x.merit_rank);if(x.verification_status!=="verified"||source?.verification_status!=="verified"||source?.document_type!=="merit_list"||!Number.isInteger(year)||!Number.isFinite(score)||score<0||score>480||!Number.isInteger(rank)||rank<1)return [];return [{exam_year:year,score,merit_rank:rank}];});
 const officialYears=[...new Set(verifiedOfficialPoints.map(x=>x.exam_year))].sort((a,b)=>a-b);
 const latestOfficialYear=officialYears.length?Math.max(...officialYears):null;
 const officialByYear=latestOfficialYear?[{year:latestOfficialYear,points:verifiedOfficialPoints.filter(x=>x.exam_year===latestOfficialYear)}]:[];
 const value=Number(input),inputValid=mode==="marks"?Number.isFinite(value)&&value>=50&&value<=480:Number.isFinite(value)&&Number.isInteger(value)&&value>=1&&value<=6500;
 const officialRankEstimates=mode==="marks"&&inputValid?officialByYear.map(g=>interpolateOfficialScoreRank(g.points,value,"marks")).filter((x):x is number=>x!==null):[];
 const officialMarksEstimates=mode==="rank"&&inputValid?officialByYear.map(g=>interpolateOfficialScoreRank(g.points,value,"rank")).filter((x):x is number=>x!==null):[];
 const rankRangeText=officialRankEstimates.length?("Official year estimates: #"+Math.round(Math.min(...officialRankEstimates)).toLocaleString("en-IN")+"–#"+Math.round(Math.max(...officialRankEstimates)).toLocaleString("en-IN")):null;
 const marksRangeText=officialMarksEstimates.length?("Official year estimates: "+Math.round(Math.min(...officialMarksEstimates)*10)/10+"–"+Math.round(Math.max(...officialMarksEstimates)*10)/10+" marks"):null;
 const loading=cutoffLoading||categoryLoading||sourceLoading||scoreRankLoading||!estimateData;
 const rankEstimate=mode==="marks"&&inputValid?(medianNumber(officialRankEstimates)??interpolateRankFromMarks(value)):null;
 const marksEstimate=mode==="rank"&&inputValid?(medianNumber(officialMarksEstimates)??interpolateMarksFromRank(value)):null;
 const marksBand=mode==="marks"&&inputValid?findMarksBand(estimateData?.bands||[],value):null;
 const rankBand=mode==="rank"&&inputValid?findRankBand(estimateData?.bands||[],value):null;
 const primaryOutput=mode==="marks"?rankEstimate?.toLocaleString("en-IN"):marksEstimate?.toLocaleString("en-IN");
 const latestCutoffYear=verified.length?Math.max(...verified.map(x=>x.year)):null;
 const nearbyByYear=latestCutoffYear?[{year:latestCutoffYear,records:verified.filter(x=>x.year===latestCutoffYear).sort((a,b)=>Math.abs((mode==="marks"?a.marks:a.rank)-value)-Math.abs((mode==="marks"?b.marks:b.rank)-value)).slice(0,4)}].filter(x=>x.records.length):[];
 const marksOutsidePublished=mode==="marks"&&value>=50&&value<=54&&!officialRankEstimates.length;
 return <Shell title="Assam CEE marks ↔ rank predictor" desc="Estimate an indicative merit rank from marks, or marks from a target rank, using SmartPrep Axom reference bands and historical admission records.">
  <section className="intel-panel predictor-parameters">
   <div className="v2-filter-heading"><Calculator/><div><b>Choose your prediction direction</b><small>Uses verified official score-to-rank records when available; otherwise falls back to published reference bands.</small></div></div>
   <div className="rank-direction-switch"><button type="button" className={mode==="marks"?"active":""} onClick={()=>{setMode("marks");setInput("200");setGenerated(false)}}><span>Marks → Rank</span><small>Estimate your merit rank from marks</small></button><button type="button" className={mode==="rank"?"active":""} onClick={()=>{setMode("rank");setInput("400");setGenerated(false)}}><span>Rank → Marks</span><small>Estimate marks for your target rank</small></button></div>
   <div className="v2-grid-2">
    <label className="v2-field"><span>{mode==="marks"?"Expected marks (50–480 / 480)":"Expected CEE merit rank (#1–#6,500)"}</span><input type="number" min={mode==="marks"?"50":"1"} max={mode==="marks"?"480":"6500"} step="1" value={input} onChange={e=>{setInput(e.target.value);setGenerated(false)}} placeholder={mode==="marks"?"Enter 50–480":"Enter rank 1–6500"}/></label>
    <div className="rank-latest-year"><b>Latest verified year:</b><strong>{latestOfficialYear??(verified.length?Math.max(...verified.map(x=>x.year)):"Reference model")}</strong></div>
   </div>
   <AnalysisEngine title={mode==="marks"?"Marks-to-rank estimate":"Rank-to-marks estimate"} subtitle={mode==="marks"?"Calculating an indicative rank from the SmartPrep Axom reference model.":"Calculating indicative marks from the SmartPrep Axom reference model."} steps={mode==="marks"?["Checking marks are within 50–480","Reading the published marks/rank bands","Comparing available historical admission records","Calculating the nearest rank estimate"]:["Checking rank is within 1–6,500","Reading the published marks/rank bands","Comparing the latest verified DTE cutoff records","Calculating the nearest marks estimate"]} durationMs={2200+Math.min(1000,(verified.length+verifiedOfficialPoints.length)*2)} mode="calculate" buttonLabel={mode==="marks"?"Calculate rank from marks":"Calculate marks from rank"} disabled={!inputValid||loading||!estimateData?.bands?.length} onComplete={()=>setGenerated(true)}/>
  </section>
  {loading?<Loading label="Loading historical admission records and SmartPrep Axom estimate data…"/>:cutoffError?<Empty title="Could not load verified cutoff data">{cutoffError}</Empty>:estimateError?<Empty title="Could not load rank reference data">{estimateError}</Empty>:generated?(mode==="marks"?<section className="intel-panel rank-result-panel"><span className="intel-eyebrow">NEAREST ESTIMATE · {verifiedOfficialPoints.length?"VERIFIED OFFICIAL MERIT-LIST DATA":"REFERENCE MODEL"}</span><h2>Estimated CEE merit rank</h2><strong className="intel-big-rank">#{primaryOutput}</strong><div className="rank-result-range">SmartPrep Axom estimate range: <b>{rankRangeText||marksBand?.rankLabel||"Interpolated between published bands"}</b></div><p>For {value} marks out of 480, the model estimates approximately rank {primaryOutput}. This is an indicative estimate. Verified official score-to-rank datasets are interpolated separately by exam year; when no such dataset is published, the SmartPrep Axom reference bands are used.</p>{marksOutsidePublished?<div className="intel-note"><Info/>50–54 marks is a short extension below the lowest published 55–70 band, capped at rank 6,500.</div>:null}</section>:<section className="intel-panel rank-result-panel"><span className="intel-eyebrow">NEAREST ESTIMATE · LATEST VERIFIED DATA</span><h2>Estimated marks out of 480</h2><strong className="intel-big-rank">{primaryOutput}</strong><div className="rank-result-range">SmartPrep Axom estimate range: <b>{marksRangeText||rankBand?.marksLabel||"Interpolated between published bands"}</b></div><p>For target merit rank #{value.toLocaleString("en-IN")}, the model estimates approximately {primaryOutput} marks. This is an indicative estimate. Verified official score-to-rank datasets are interpolated separately by exam year; when no such dataset is published, the SmartPrep Axom reference bands are used.</p></section>):<section className="intel-panel rank-empty-state"><b>Ready to calculate</b><p>Marks input accepts every value from 50 to 480. Rank input accepts #1 to #6,500.</p><small>Example: 200 marks gives an indicative estimate around rank 446, within the published 301–500 band.</small></section>}
  <section className="intel-panel"><div className="cea-section-head"><div><span className="cea-kicker">HISTORICAL ADMISSION DATA</span><h2>Latest verified cutoff comparisons</h2></div><span className="cea-pill">{fmt(verified.length)} records</span></div><p className="intel-muted">These are historical college and branch closing cutoffs. They are useful for comparing admission trends, but they are not individual candidate rank records.</p>{generated&&nearbyByYear.length?<div className="v2-cutoff-list">{nearbyByYear.map(group=><React.Fragment key={group.year}><div style={{padding:"12px 0 4px",fontWeight:800}}>CEE {group.year}</div>{group.records.map((p,i)=><article key={group.year+"-"+p.rank+"-"+p.marks+"-"+i}><div><b>{p.college}</b><small>{p.branch} · {p.round} · {p.quota==="5_percent_reservation"?"5% reservation":p.quota==="excluding_5_percent"?"excluding 5%":"all seats"}</small></div><div><strong>#{fmt(p.rank)}</strong><small>Closing rank</small></div><span>{fmt(p.marks)} marks</span></article>)}</React.Fragment>)}</div>:<Empty title="Run an estimate to inspect historical cutoffs">The closest historical college and branch cutoff pairs will be shown separately by year.</Empty>}</section>
  <div className="smartprep-source">Source: SmartPrep Axom</div>
 </Shell>
}
function College(){
 const {rows:cutoffs,loading:cl,error:cutoffError}=useRows("admission_cutoffs","id,admission_year,institution_id,branch_id,category_id,counselling_round_id,quota_code,opening_rank,closing_rank,closing_marks,seat_intake,seat_type,source_file,source_page,verification_status");
 const {rows:inst}=useRows("engineering_institutions","id,code,name,city");
 const {rows:branches}=useRows("engineering_branches","id,code,name");
 const {rows:cats}=useRows("admission_categories","id,code,name");
 const {rows:rounds}=useRows("counselling_rounds","id,admission_year,round_code,round_name");
 const [input,setInput]=useState(""),[metric,setMetric]=useState("rank"),[cat,setCat]=useState("UR"),[quota,setQuota]=useState("all"),[branch,setBranch]=useState("all"),[college,setCollege]=useState("all"),[generated,setGenerated]=useState(false);
 const [expanded,setExpanded]=useState<string[]>([]);
 const availableYears=[...new Set(cutoffs.filter(x=>x.verification_status==="verified").map(x=>Number(x.admission_year)).filter(y=>y>=2023))].sort((a,b)=>a-b);
 const years=availableYears.length?[availableYears[availableYears.length-1]]:[];
 const referenceCutoffs=cutoffs.filter(x=>years.includes(Number(x.admission_year))&&x.verification_status==="verified");
 const value=Number(input),valid=metric==="rank"?Number.isInteger(value)&&value>=1&&value<=6500:Number.isFinite(value)&&value>=50&&value<=480;
 const branchOptions=branches.filter(b=>referenceCutoffs.some(x=>(college==="all"||x.institution_id===college)&&x.branch_id===b.id&&isOfficialBranch(inst.find(i=>i.id===x.institution_id)?.name,b.name)));
 const rows:R[]=referenceCutoffs.filter(x=>(!cat||cats.find(c=>c.id===x.category_id)?.code===cat)&&(quota==="all"||x.quota_code===quota)&&(branch==="all"||x.branch_id===branch)&&(college==="all"||x.institution_id===college))
  .map((x):R=>({...x,inst:inst.find(i=>i.id===x.institution_id),br:branches.find(b=>b.id===x.branch_id),category:cats.find(c=>c.id===x.category_id),rd:rounds.find(r=>r.id===x.counselling_round_id)}))
  .filter(x=>isOfficialBranch(x.inst?.name,x.br?.name));
 const groups=(()=>{
  const map=new Map<string,{key:string;collegeId:string;collegeName:string;branchId:string;branchName:string;records:R[];status:"match"|"near"|"outside";gap:number}>();
  rows.forEach(x=>{const key=String(x.institution_id)+"::"+String(x.branch_id);const old=map.get(key);if(old){old.records.push(x);return;}map.set(key,{key,collegeId:String(x.institution_id),collegeName:x.inst?.name||"Engineering college",branchId:String(x.branch_id),branchName:x.br?.name||"Branch",records:[x],status:"outside",gap:Infinity});});
  return [...map.values()].map(g=>{
   const validRecords=g.records.filter(x=>metric==="rank"?Number(x.closing_rank)>0:Number(x.closing_marks)>0);
   const matched=validRecords.filter(x=>metric==="rank"?value<=Number(x.closing_rank):value>=Number(x.closing_marks));
   const gaps=validRecords.map(x=>metric==="rank"?Math.max(0,value-Number(x.closing_rank)):Math.max(0,Number(x.closing_marks)-value));
   const bestGap=gaps.length?Math.min(...gaps):Infinity;
   const tolerance=metric==="rank"?Math.max(75,value*.08):Math.max(8,value*.08);
   return {...g,status:(matched.length?"match":bestGap<=tolerance?"near":"outside") as "match"|"near"|"outside",gap:matched.length?0:bestGap};
  }).filter(g=>g.status!=="outside").sort((a,b)=>(a.status==="match"?0:1)-(b.status==="match"?0:1)||a.gap-b.gap||a.collegeName.localeCompare(b.collegeName));
 })();
 const collegeCount=new Set(groups.map(g=>g.collegeId)).size,matchedCount=groups.filter(g=>g.status==="match").length;
 const toggle=(key:string)=>setExpanded(old=>old.includes(key)?old.filter(x=>x!==key):[...old,key]);
 const statusLabel=(s:"match"|"near"|"outside")=>s==="match"?"Within historical cutoff":"Near historical cutoff";
 return <Shell title="Assam CEE college predictor" desc="Explore college and branch options using your expected merit rank or marks, category and seat preferences.">
  <section className="intel-panel college-predictor-panel">
   <div className="college-predictor-heading"><span className="college-predictor-icon"><GraduationCap/></span><div><span className="intel-eyebrow">SMART ADMISSION PLANNER</span><h2>Find your college options</h2><p>Enter your score, choose your preferences and generate a personalised shortlist.</p></div></div>
   <div className="college-metric-switch" role="group" aria-label="Prediction input type">
    <button type="button" className={metric==="rank"?"active":""} onClick={()=>{setMetric("rank");setInput("");setGenerated(false)}}><span>Merit rank</span><small>Predict using your rank</small></button>
    <button type="button" className={metric==="marks"?"active":""} onClick={()=>{setMetric("marks");setInput("");setGenerated(false)}}><span>Exam marks</span><small>Predict using your marks</small></button>
   </div>
   <div className="college-input-card">
    <label className="college-score-field"><span>{metric==="rank"?"YOUR EXPECTED CEE RANK":"YOUR EXPECTED CEE MARKS"}</span><div><input type="number" min={metric==="rank"?"1":"50"} max={metric==="rank"?"6500":"480"} step="1" value={input} onChange={e=>{setInput(e.target.value);setGenerated(false)}} placeholder={metric==="rank"?"Enter rank (e.g. 1500)":"Enter marks (50–480)"}/><small>{metric==="rank"?"Rank range #1–#6,500":"Maximum 480 marks"}</small></div></label>
    <div className="college-filter-grid">
     <Select label="Category" value={cat} onChange={v=>{setCat(v);setGenerated(false)}}><option value="">All categories</option>{cats.map(x=><option key={x.id} value={x.code}>{x.code} · {x.name}</option>)}</Select>
     <Select label="Seat / quota" value={quota} onChange={v=>{setQuota(v);setGenerated(false)}}><option value="all">All seat types</option><option value="all_seats">All seats</option><option value="excluding_5_percent">Excluding 5% reservation</option><option value="5_percent_reservation">5% reservation</option></Select>
     <Select label="Preferred college" value={college} onChange={v=>{setCollege(v);setBranch("all");setGenerated(false)}}><option value="all">All colleges</option>{inst.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</Select>
     <Select label="Preferred branch" value={branch} onChange={v=>{setBranch(v);setGenerated(false)}}><option value="all">All available branches</option>{branchOptions.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</Select>
    </div>
   </div>
   <AnalysisEngine title="Building your college shortlist" subtitle="Matching your expected score with historical college and branch cutoffs." steps={["Checking your rank or marks","Applying your category and seat preferences","Comparing available college and branch cutoffs","Organising your best-matching options"]} durationMs={2100+Math.min(1500,referenceCutoffs.length/10)} mode="match" buttonLabel="Generate my college prediction" disabled={!valid||cl||!rows.length} onComplete={()=>{setGenerated(true);setExpanded(groups.slice(0,3).map(g=>g.key))}}/>
   <div className="college-predictor-foot"><span><ShieldCheck/> Personalised historical comparison</span><span>{years.length?"Latest verified data: "+years[0]:"No verified cutoff data"}</span></div>
  </section>
  {cl?<Loading label="Loading college and branch records…"/>:cutoffError?<Empty title="Could not load college records">{cutoffError}</Empty>:!rows.length?<Empty title="No historical records available">Try another category, quota, college or branch selection.</Empty>:generated?<>
   <section className="college-results-summary">
    <div><span>COLLEGE OPTIONS</span><strong>{fmt(collegeCount)}</strong><small>Colleges with a historical match or near match</small></div>
    <div><span>WITHIN CUTOFF</span><strong>{fmt(matchedCount)}</strong><small>At least one round met the historical cutoff</small></div>
    <div><span>YOUR {metric==="rank"?"RANK":"MARKS"}</span><strong>{metric==="rank"?"#":""}{fmt(value)}</strong><small>{years.join(" · ")} historical comparison</small></div>
   </section>
   <section className="college-results-section">
    <div className="college-results-title"><div><span className="intel-eyebrow">YOUR MATCHED OPTIONS</span><h2>College predictions</h2><p>{groups.length} college and branch combinations found for your selected preferences.</p></div><span className="college-result-count">{fmt(groups.length)} options</span></div>
    {groups.length?<div className="college-result-list">{groups.map((g,index)=>{
     const isOpen=expanded.includes(g.key),byYear=years.map(year=>({year,records:g.records.filter(x=>Number(x.admission_year)===year).sort((a,b)=>Number(a.closing_rank)-Number(b.closing_rank))}));
     return <article className={"college-result-card "+(g.status==="match"?"is-match":"is-near")} key={g.key}>
      <button type="button" className="college-result-toggle" onClick={()=>toggle(g.key)} aria-expanded={isOpen}>
       <span className="college-result-rank">{String(index+1).padStart(2,"0")}</span>
       <span className="college-result-main"><b>{g.collegeName}</b><small>{g.branchName}</small><em className={g.status==="match"?"status-match":"status-near"}>{statusLabel(g.status)}</em></span>
       <span className="college-result-action">{isOpen?"−":"+"}</span>
      </button>
      {isOpen?<div className="college-year-comparison">{byYear.map(group=><section className="college-year-card" key={group.year}><h3>{group.year}</h3>{group.records.length?group.records.map(x=><div className="college-round-row" key={x.id}><span>{x.rd?.round_name||"Counselling round"}</span><div><b>{x.closing_rank?"#"+fmt(x.closing_rank):"—"}</b><small>Closing rank</small></div><div><b>{x.closing_marks!=null?fmt(x.closing_marks):"—"}</b><small>Marks</small></div></div>):<p className="college-no-year">No record</p>}</section>)}</div>:null}
     </article>;
    })}</div>:<Empty title="No close historical options">No college or branch cutoff is close to this input under the selected filters. Try a different category or preference.</Empty>}
   </section>
   <div className="smartprep-source">Source: SmartPrep Axom</div>
  </>:<section className="intel-panel college-ready-panel"><div className="college-ready-icon"><Sparkles/></div><h2>Your college shortlist is one step away</h2><p>Enter your expected {metric==="rank"?"merit rank":"exam marks"}, select your preferences and generate a comparison across the available counselling years.</p><div className="college-ready-steps"><span>01 · Enter score</span><span>02 · Set preferences</span><span>03 · Generate options</span></div><div className="smartprep-source">Source: SmartPrep Axom</div></section>}
 </Shell>;
}
function CutoffAnalysis(){
 const {rows:c,loading}=useRows("admission_cutoffs","id,admission_year,institution_id,branch_id,category_id,counselling_round_id,quota_code,opening_rank,closing_rank,closing_marks,seat_type,verification_status");
 const {rows:i}=useRows("engineering_institutions","id,code,name");
 const {rows:b}=useRows("engineering_branches","id,code,name");
 const {rows:g}=useRows("admission_categories","id,code,name");
 const {rows:r}=useRows("counselling_rounds","id,admission_year,round_name");
 const [subject,setSubject]=useState("all"),[cat,setCat]=useState("all"),[quota,setQuota]=useState("all"),[query,setQuery]=useState(""),[analysed,setAnalysed]=useState(false);
 const availableReferenceYears=[...new Set(c.filter(x=>x.verification_status==="verified").map(x=>Number(x.admission_year)).filter(y=>y>=2023))].sort((a,b)=>a-b);
 const referenceYears=availableReferenceYears.length?[availableReferenceYears[availableReferenceYears.length-1]]:[];
 const filtered:R[]=c.filter(x=>referenceYears.includes(Number(x.admission_year))&&x.verification_status==="verified"&&(subject==="all"||x.institution_id===subject)&&(cat==="all"||x.category_id===cat)&&(quota==="all"||x.quota_code===quota))
 .map((x):R=>({...x,inst:i.find(y=>y.id===x.institution_id),br:b.find(y=>y.id===x.branch_id),rd:r.find(y=>y.id===x.counselling_round_id)}))
 .filter(x=>isOfficialBranch(x.inst?.name,x.br?.name))
 .filter(x=>(x.inst?.name+" "+x.br?.name+" "+x.quota_code).toLowerCase().includes(query.toLowerCase()))
 .sort((a,b)=>Number(a.closing_rank)-Number(b.closing_rank));
 return <Shell title="College cutoff trends" desc="Explore verified historical closing-rank and marks records from published admission sources. Always check the latest official counselling information before making a choice.">
 <section className="intel-panel v2-filter-panel"><div className="v2-filter-heading"><GraduationCap/><div><b>Latest verified cutoff dataset</b><small>Records checked against published admission sources · all available rounds</small></div></div>
 <div className="v2-grid-3"><div className="v2-fixed-field"><span>Reference data</span><strong>Latest verified data</strong></div>
 <Select label="College" value={subject} onChange={v=>{setSubject(v);setAnalysed(false)}}><option value="all">All colleges</option>{i.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</Select>
 <Select label="Category" value={cat} onChange={v=>{setCat(v);setAnalysed(false)}}><option value="all">All categories</option>{g.map(x=><option key={x.id} value={x.id}>{x.code}</option>)}</Select>
 <Select label="Quota" value={quota} onChange={v=>{setQuota(v);setAnalysed(false)}}><option value="all">All quota types</option><option value="all_seats">All seats</option><option value="excluding_5_percent">Excluding 5%</option><option value="5_percent_reservation">5% reservation</option></Select>
 <div className="v2-fixed-field"><span>Counselling rounds</span><strong>All rounds</strong></div></div>
 <label className="intel-search v2-search"><Search/><input value={query} onChange={e=>{setQuery(e.target.value);setAnalysed(false)}} placeholder="Search college or available branch"/></label></section>
 {loading?<Loading/>:<><AnalysisEngine title="College cutoff explorer" subtitle="Searching verified admission records and applying your selected college, category and quota filters." steps={["Loading verified counselling records","Applying college and category filters","Matching quota and branch records","Building cutoff comparison"]} durationMs={1700+Math.min(1700,filtered.length*3)} mode="analyse" buttonLabel="Analyse cutoff records" onComplete={()=>setAnalysed(true)}/>{analysed&&<><div className="intel-stats"><Stat label="Matching records" value={fmt(filtered.length)}/><Stat label="Reference data" value="Latest verified"/><Stat label="Colleges" value={fmt(new Set(filtered.map(x=>x.institution_id)).size)}/></div>
 {filtered.length?<div className="v2-cutoff-list">{filtered.map(x=><article key={x.id}><div><b>{x.inst?.name}</b><small>{x.br?.name} · {g.find(y=>y.id===x.category_id)?.code} · {x.rd?.round_name}</small></div><div><strong>#{fmt(x.closing_rank)}</strong><small>Closing rank</small></div><span>{x.closing_marks==null?"Marks not supplied":fmt(x.closing_marks)+" marks"}</span></article>)}</div>:<Empty title="No cutoff rows match these filters">No verified records match the selected college, category and quota in the combined reference dataset.</Empty>}<div className="intel-note"><Info/>These records are for historical comparison only. They do not show current vacancies or guarantee an allotment. Before filling choices, confirm the latest seat matrix, eligibility, category and quota rules, counselling schedule and official round-wise results on ASTU and DTE Assam websites. SmartPrep Axom is an independent platform and is not affiliated with either authority.</div></>}
 </>}
 </Shell>;
}
